import { expect, test, type Page } from "@playwright/test";
import { existsSync, readdirSync, rmSync } from "node:fs";
import path from "node:path";
import { launchPackagedApp, type LaunchedApp } from "./launch";

// Generated by `npm run fixtures`: an 8 s vertical clip.
const CLIP = path.resolve("fixtures", "vertical_1080x1920_30.mp4");
const FULL = "Aloe Vera Gel";
const SLUG = "aloe-vera-gel";
const BANK_TEXT = "I can't fix my smile";

let launched: LaunchedApp;
let page: Page;

test.beforeAll(async () => {
  test.skip(!existsSync(CLIP), 'Run "npm run fixtures" first.');
  launched = await launchPackagedApp();
  page = await launched.app.firstWindow();
});

test.afterAll(async () => {
  await launched?.app.close();
});

const nav = (name: string) =>
  page.getByRole("button", { name, exact: true }).first().click();
const slot = (name: "before" | "after" | "broll") =>
  page.getByTestId(`slot-${name}`);
const exportButton = () =>
  page.getByRole("button", { name: "Export", exact: true });
const rows = () => page.getByTestId("history-row");

async function buildVideo(): Promise<void> {
  await page.getByLabel("Before clip file").setInputFiles([CLIP]);
  await page.getByLabel("After clip file").setInputFiles([CLIP]);
  await expect(slot("before")).toHaveAttribute("data-status", "ready", {
    timeout: 90_000,
  });
  await expect(slot("after")).toHaveAttribute("data-status", "ready", {
    timeout: 90_000,
  });
  await slot("broll").getByRole("button", { name: "Choose b-roll" }).click();
  await page.getByRole("dialog").getByRole("option").first().click();
  await expect(slot("broll")).toHaveAttribute("data-status", "ready");
  await slot("before").getByRole("heading", { name: "Before" }).click();
  await page.getByTestId("caption-pick").click();
  await page
    .getByRole("dialog", { name: "Choose a caption" })
    .getByRole("option", { name: new RegExp(BANK_TEXT) })
    .click();
  await expect(exportButton()).toBeEnabled();
}

async function exportAndWait(): Promise<string> {
  await exportButton().click();
  const done = page.getByRole("dialog", { name: "Your video is ready" });
  await expect(done).toBeVisible({ timeout: 240_000 });
  return (await done.getByTestId("export-file-name").textContent()) ?? "";
}

function exportsFolder(): string {
  const productDir = path.join(launched.libraryDir, "exports", SLUG);
  const [dateDir] = readdirSync(productDir);
  return path.join(productDir, dateDir ?? "");
}

const rowOf = (fileName: string) => rows().filter({ hasText: fileName });

test("history: grouped rows, missing files, delete record with and without the file", async () => {
  test.setTimeout(900_000);

  await test.step("stub Show in Finder and the Trash, then set up a product", async () => {
    // The Trash is replaced by a fake that records and unlinks: the suite must never put
    // files into the real macOS Trash.
    await launched.app.evaluate(({ shell }) => {
      const g = globalThis as { __revealed?: string[]; __trashed?: string[] };
      g.__revealed = [];
      g.__trashed = [];
      shell.showItemInFolder = (p: string) => {
        g.__revealed?.push(p);
      };
      const { unlink } = process.getBuiltinModule("node:fs/promises");
      shell.trashItem = async (p: string) => {
        g.__trashed?.push(p);
        await unlink(p);
      };
    });
    await page.getByRole("button", { name: "Choose another folder" }).click();
    await page.getByRole("button", { name: "Use this folder" }).click();
    await page.getByRole("button", { name: "Add your first product" }).click();
    const dialog = page.getByRole("dialog", { name: "Add product" });
    await dialog.getByLabel("Full name").fill(FULL);
    await dialog.getByRole("button", { name: "Add product" }).click();
    await expect(dialog).toBeHidden();
    await page
      .getByRole("listitem")
      .filter({ hasText: FULL })
      .getByRole("button", { name: new RegExp(FULL) })
      .first()
      .click();
    await page.getByLabel("B-roll files").setInputFiles([CLIP]);
    await expect(page.getByTestId("broll-duration")).toHaveCount(1, {
      timeout: 90_000,
    });
    await page.evaluate(async (text) => {
      const [product] = await window.api.products.list();
      const created = await window.api.captions.create({
        text,
        slot: "before",
        productId: product.id,
      });
      if (!created.ok) {
        throw new Error(created.message);
      }
    }, BANK_TEXT);
  });

  await test.step("empty History explains itself", async () => {
    await nav("History");
    await expect(page.getByText(/^No videos yet/)).toBeVisible();
    await expect(rows()).toHaveCount(0);
  });

  let first = "";
  let second = "";
  await test.step("export two videos and start a third draft", async () => {
    await nav("New Video");
    await page.getByRole("option", { name: new RegExp(FULL) }).click();
    await buildVideo();
    first = await exportAndWait();
    await page.getByRole("button", { name: "New video, same product" }).click();
    await buildVideo();
    second = await exportAndWait();
    await page.getByRole("button", { name: "New video, same product" }).click();
    await page.getByLabel("Before clip file").setInputFiles([CLIP]);
    await expect(slot("before")).toHaveAttribute("data-status", "ready", {
      timeout: 90_000,
    });
  });

  await test.step("History groups them under the product with thumbnail, name, length and status", async () => {
    await nav("History");
    await expect(
      page.getByRole("heading", { name: FULL, exact: true }),
    ).toBeVisible();
    await expect(rows()).toHaveCount(3);
    const a = rowOf(first);
    await expect(a).toHaveAttribute("data-badge", "Exported");
    await expect(a).toContainText("12.0s");
    await expect(rowOf(second)).toHaveAttribute("data-badge", "Exported");
    const draftRow = page.locator(
      '[data-testid="history-row"][data-status="draft"]',
    );
    await expect(draftRow).toContainText("1 of 3 clips");
    // The Before clip's thumbnail really loads (not a broken image).
    for (const row of [a, draftRow]) {
      await expect
        .poll(() =>
          row
            .locator("img")
            .evaluate((img: HTMLImageElement) => img.naturalWidth),
        )
        .toBeGreaterThan(0);
    }
  });

  await test.step("Show in Finder reveals the exported file", async () => {
    await rowOf(first)
      .getByRole("button", { name: /^Show in (Finder|Explorer)$/ })
      .click();
    await expect
      .poll(() =>
        launched.app.evaluate(
          () => (globalThis as { __revealed?: string[] }).__revealed ?? [],
        ),
      )
      .toEqual([path.join(exportsFolder(), first)]);
  });

  await test.step("an mp4 deleted outside the app reads File missing", async () => {
    rmSync(path.join(exportsFolder(), second));
    await nav("Products");
    await nav("History");
    const b = rowOf(second);
    await expect(b).toHaveAttribute("data-badge", "File missing");
    await expect(
      b.getByRole("button", { name: /^Show in (Finder|Explorer)$/ }),
    ).toHaveCount(0);
  });

  await test.step("delete a record whose file is gone: no Trash checkbox, sidecar stays", async () => {
    const b = rowOf(second);
    await b.getByRole("button", { name: "Delete" }).click();
    const dialog = page.getByRole("dialog", { name: "Delete from history" });
    await expect(dialog.getByRole("checkbox")).toHaveCount(0);
    await dialog.getByRole("button", { name: "Delete" }).click();
    await expect(dialog).toBeHidden();
    await expect(rows()).toHaveCount(2);
    expect(
      existsSync(
        path.join(exportsFolder(), second.replace(/\.mp4$/, ".recipe.json")),
      ),
    ).toBe(true);
  });

  await test.step("delete a record and move its files to the Trash", async () => {
    const a = rowOf(first);
    await a.getByRole("button", { name: "Delete" }).click();
    const dialog = page.getByRole("dialog", { name: "Delete from history" });
    const box = dialog.getByRole("checkbox");
    await expect(box).not.toBeChecked();
    await box.check();
    await dialog.getByRole("button", { name: "Delete" }).click();
    await expect(dialog).toBeHidden();
    await expect(rows()).toHaveCount(1);
    const trashed = await launched.app.evaluate(
      () => (globalThis as { __trashed?: string[] }).__trashed ?? [],
    );
    expect(trashed.map((p) => path.basename(p))).toEqual([
      first,
      first.replace(/\.mp4$/, ".recipe.json"),
    ]);
    expect(existsSync(path.join(exportsFolder(), first))).toBe(false);
  });

  await test.step("a clip deleted from the library: no preview in History, missing in the editor", async () => {
    const clipPath = await page.evaluate(async () => {
      const [draft] = await window.api.videos.list({ status: "draft" });
      return (
        JSON.parse(draft.recipeJson) as { clips: { mediaPath: string }[] }
      ).clips[0].mediaPath;
    });
    rmSync(path.join(launched.libraryDir, ...clipPath.split("/")));
    await nav("Products");
    await nav("History");
    const draftRow = page.locator(
      '[data-testid="history-row"][data-status="draft"]',
    );
    await expect(draftRow.getByTestId("history-no-preview")).toBeVisible();
    await draftRow.getByRole("button", { name: "Open" }).click();
    await expect(slot("before")).toHaveAttribute("data-status", "missing");
  });
});
